		return gx.Frag(Example(ExampleProps{Item: "data-table", Name: "data-table-three", Label: "Data Table: Three", Children: gxContentMarkdown("\n\n```gx\n{datatable.DataTable(datatable.DataTableFixtures[\"Three\"])}\n```\n\nThe code renders the fixture by its name. The fixture sets these props.\n\n```go title=\"registry/data-table/DataTable.fixtures.go\"\n\"Three\": {\n  Columns: []Column[fixtureRow]{\n    {Key: \"name\", Label: \"Name\", Sort: \"name\", Cell: func(r fixtureRow) gx.Node { return gx.Text(r.Name) }},\n    {Key: \"total\", Label: \"Total\", Cell: func(r fixtureRow) gx.Node { return gx.Text(strconv.Itoa(r.Total)) }},\n  },\n  Rows: []fixtureRow{{Name: \"Alpha\", Total: 10}, {Name: \"Beta\", Total: 20}, {Name: \"Gamma\", Total: 30}},\n  Page: Page{Number: 1, Size: 10, Total: 3},\n  Href: func(sort, dir string, page int) gx.URL { return gx.URL(\"/\") },\n}\n```\n\n")}), docs.Aside(docs.AsideProps{Kind: docs.Note, Title: "Static preview", Children: gxContentMarkdown("\n\nThis page shows static fixtures. The live behaviour needs a server.\n\n")}), gxContentMarkdown("\n\n## Installation\n\n"), docs.Tabs(docs.TabsProps{Sync: "install", Children: gx.Frag(docs.TabItem(docs.TabItemProps{Label: "CLI", Children: gxContentMarkdown("\n\nRun the command in the app module.\n\n```sh frame=\"terminal\" title=\"Terminal\"\ngx add data-table\n```\n\nThe command also installs [`table`](/components/table/) and [`pagination`](/components/pagination/).\n\nThe command writes these files.\n\n| File | Path in the app |\n| --- | --- |\n| `DataTable.go` | `ui/data-table/DataTable.go` |\n| `DataTable.fixtures.go` | `ui/data-table/DataTable.fixtures.go` |\n\n")}), docs.TabItem(docs.TabItemProps{Label: "Manual", Children: gxContentMarkdown("\n\nInstall [`table`](/components/table/) and [`pagination`](/components/pagination/) first.\n\nCopy each file to its path in the app. Change each import of a registry package to the path of that package in the app.\n\n```go title=\"ui/data-table/DataTable.go\"\n// Package datatable renders a server-driven table (REQ-REG-10). Sort,\n// filter and paging state live in typed GET routes; the component only\n// renders one page and links the next one.\npackage datatable\n\nimport (\n\t\"strconv\"\n\n\t\"github.com/alternayte/gx\"\n\t\"github.com/alternayte/gx/registry/pagination\"\n\t\"github.com/alternayte/gx/registry/table\"\n)\n\n// Column is one typed column of a data table.\ntype Column[T any] struct {\n\t// Key identifies the column in the row data.\n\tKey string\n\t// Label is the visible header text.\n\tLabel string\n\t// Cell renders one cell.\n\tCell func(T) gx.Node\n\t// Sort is the query value of the column when the header is a sort\n\t// link. Empty makes the column unsortable.\n\tSort string\n}\n\n// Page is the paging state of one table render.\ntype Page struct {\n\tNumber int\n\tSize   int\n\tTotal  int\n}\n\n// Href builds the typed GET URL of one table state. The app returns its\n// own route value, so the query stays typed.\ntype Href func(sort, dir string, page int) gx.URL\n\n// DataTableProps holds one rendered table.\ntype DataTableProps[T any] struct {\n\tColumns []Column[T]\n\tRows    []T\n\tPage    Page\n\tSort    string\n\tDir     string\n\tHref    Href\n\t// Empty renders in place of the rows when the page holds none.\n\tEmpty gx.Node\n}\n\n// DataTable renders one page of a server-driven table with sortable\n// headers and paging links (REQ-REG-10).\nfunc DataTable[T any](p DataTableProps[T]) gx.Node {\n\thead := make([]gx.Node, 0, len(p.Columns))\n\tfor _, col := range p.Columns {\n\t\thead = append(head, header(p, col))\n\t}\n\tbody := make([]gx.Node, 0, len(p.Rows))\n\tfor _, row := range p.Rows {\n\t\tcells := make([]gx.Node, 0, len(p.Columns))\n\t\tfor _, col := range p.Columns {\n\t\t\tcells = append(cells, table.TableCell(table.TableCellProps{Children: col.Cell(row)}))\n\t\t}\n\t\tbody = append(body, table.TableRow(table.TableRowProps{Children: gx.Frag(cells...)}))\n\t}\n\tvar rows gx.Node\n\tswitch {\n\tcase len(p.Rows) > 0:\n\t\trows = gx.Frag(body...)\n\tcase p.Empty != nil:\n\t\trows = table.TableRow(table.TableRowProps{\n\t\t\tChildren: table.TableCell(table.TableCellProps{\n\t\t\t\tClass:    \"h-24 text-center text-muted-foreground\",\n\t\t\t\tChildren: p.Empty,\n\t\t\t}),\n\t\t})\n\tdefault:\n\t\trows = table.TableRow(table.TableRowProps{\n\t\t\tChildren: table.TableCell(table.TableCellProps{\n\t\t\t\tClass:    \"h-24 text-center text-muted-foreground\",\n\t\t\t\tChildren: gx.Text(\"No results.\"),\n\t\t\t}),\n\t\t})\n\t}\n\tparts := []gx.Node{\n\t\ttable.Table(table.TableProps{Children: gx.Frag(\n\t\t\ttable.TableHeader(table.TableHeaderProps{Children: table.TableRow(table.TableRowProps{Children: gx.Frag(head...)})}),\n\t\t\ttable.TableBody(table.TableBodyProps{Children: rows}),\n\t\t)}),\n\t}\n\tif p.Page.Size > 0 {\n\t\tparts = append(parts, paging(p))\n\t}\n\treturn gx.Frag(parts...)\n}\n\n// header renders one header cell, with a sort link when the column sorts.\nfunc header[T any](p DataTableProps[T], col Column[T]) gx.Node {\n\tif col.Sort == \"\" {\n\t\treturn table.TableHead(table.TableHeadProps{Children: gx.Text(col.Label)})\n\t}\n\tdir := \"asc\"\n\tarrow := \"↕\"\n\tattrs := gx.Attrs{}\n\tif p.Sort == col.Sort {\n\t\tswitch p.Dir {\n\t\tcase \"desc\":\n\t\t\tdir = \"asc\"\n\t\t\tarrow = \"↓\"\n\t\t\tattrs = append(attrs, gx.Attr{Key: \"aria-sort\", Value: \"descending\"})\n\t\tdefault:\n\t\t\tdir = \"desc\"\n\t\t\tarrow = \"↑\"\n\t\t\tattrs = append(attrs, gx.Attr{Key: \"aria-sort\", Value: \"ascending\"})\n\t\t}\n\t}\n\tlink := gx.El(\"a\", gx.Attrs{\n\t\t{Key: \"href\", Value: string(p.Href(col.Sort, dir, 1)), Kind: gx.AttrURL},\n\t\t{Key: \"class\", Value: \"inline-flex items-center gap-1 no-underline hover:text-foreground\"},\n\t}, gx.Text(col.Label), gx.El(\"span\", gx.Attrs{{Key: \"class\", Value: \"text-muted-foreground\"}}, gx.Text(arrow)))\n\treturn table.TableHead(table.TableHeadProps{Attrs: attrs, Children: link})\n}\n\n// paging renders the footer with the row range and the page links.\nfunc paging[T any](p DataTableProps[T]) gx.Node {\n\tpages := (p.Page.Total + p.Page.Size - 1) / p.Page.Size\n\tif pages < 1 {\n\t\tpages = 1\n\t}\n\tnumber := p.Page.Number\n\tif number < 1 {\n\t\tnumber = 1\n\t}\n\tif number > pages {\n\t\tnumber = pages\n\t}\n\tfrom := (number-1)*p.Page.Size + 1\n\tto := from + len(p.Rows) - 1\n\tif p.Page.Total == 0 {\n\t\tfrom, to = 0, 0\n\t}\n\titems := []gx.Node{\n\t\tpagination.PaginationItem(pagination.PaginationItemProps{Children: pagination.PaginationPrevious(pagination.PaginationPreviousProps{\n\t\t\tHref:  p.Href(p.Sort, p.Dir, number-1),\n\t\t\tClass: previousClass(number),\n\t\t})}),\n\t}\n\tfor _, page := range pageWindow(number, pages) {\n\t\tpage := page\n\t\tif page == 0 {\n\t\t\titems = append(items, pagination.PaginationItem(pagination.PaginationItemProps{\n\t\t\t\tChildren: pagination.PaginationEllipsis(pagination.PaginationEllipsisProps{}),\n\t\t\t}))\n\t\t\tcontinue\n\t\t}\n\t\titems = append(items, pagination.PaginationItem(pagination.PaginationItemProps{\n\t\t\tChildren: pagination.PaginationLink(pagination.PaginationLinkProps{\n\t\t\t\tHref:     p.Href(p.Sort, p.Dir, page),\n\t\t\t\tActive:   page == number,\n\t\t\t\tChildren: gx.Text(strconv.Itoa(page)),\n\t\t\t}),\n\t\t}))\n\t}\n\titems = append(items, pagination.PaginationItem(pagination.PaginationItemProps{Children: pagination.PaginationNext(pagination.PaginationNextProps{\n\t\tHref:  p.Href(p.Sort, p.Dir, number+1),\n\t\tClass: nextClass(number, pages),\n\t})}))\n\treturn gx.El(\"div\", gx.Attrs{{Key: \"class\", Value: \"flex items-center justify-between gap-4 px-2 pt-4\"}},\n\t\tgx.El(\"p\", gx.Attrs{{Key: \"class\", Value: \"text-sm text-muted-foreground\"}},\n\t\t\tgx.Text(strconv.Itoa(from)+\"–\"+strconv.Itoa(to)+\" of \"+strconv.Itoa(p.Page.Total))),\n\t\tpagination.Pagination(pagination.PaginationProps{Children: pagination.PaginationContent(pagination.PaginationContentProps{Children: gx.Frag(items...)})}),\n\t)\n}\n\n// previousClass hides the previous link on the first page.\nfunc previousClass(number int) string {\n\tif number <= 1 {\n\t\treturn \"pointer-events-none opacity-50\"\n\t}\n\treturn \"\"\n}\n\n// nextClass hides the next link on the last page.\nfunc nextClass(number, pages int) string {\n\tif number >= pages {\n\t\treturn \"pointer-events-none opacity-50\"\n\t}\n\treturn \"\"\n}\n\n// pageWindow returns the page numbers to show, with 0 for an ellipsis.\nfunc pageWindow(number, pages int) []int {\n\tif pages <= 7 {\n\t\tout := make([]int, 0, pages)\n\t\tfor i := 1; i <= pages; i++ {\n\t\t\tout = append(out, i)\n\t\t}\n\t\treturn out\n\t}\n\tout := []int{1}\n\tstart, end := number-1, number+1\n\tif start < 2 {\n\t\tstart, end = 2, 4\n\t}\n\tif end > pages-1 {\n\t\tstart, end = pages-4, pages-1\n\t}\n\tif start > 2 {\n\t\tout = append(out, 0)\n\t}\n\tfor i := start; i <= end; i++ {\n\t\tout = append(out, i)\n\t}\n\tif end < pages-1 {\n\t\tout = append(out, 0)\n\t}\n\treturn append(out, pages)\n}\n```\n\n```go title=\"ui/data-table/DataTable.fixtures.go\"\npackage datatable\n\nimport (\n\t\"strconv\"\n\n\t\"github.com/alternayte/gx\"\n)\n\ntype fixtureRow struct {\n\tName  string\n\tTotal int\n}\n\nvar DataTableFixtures = gx.Fixtures[DataTableProps[fixtureRow]]{\n\t\"Three\": {\n\t\tColumns: []Column[fixtureRow]{\n\t\t\t{Key: \"name\", Label: \"Name\", Sort: \"name\", Cell: func(r fixtureRow) gx.Node { return gx.Text(r.Name) }},\n\t\t\t{Key: \"total\", Label: \"Total\", Cell: func(r fixtureRow) gx.Node { return gx.Text(strconv.Itoa(r.Total)) }},\n\t\t},\n\t\tRows: []fixtureRow{{Name: \"Alpha\", Total: 10}, {Name: \"Beta\", Total: 20}, {Name: \"Gamma\", Total: 30}},\n\t\tPage: Page{Number: 1, Size: 10, Total: 3},\n\t\tHref: func(sort, dir string, page int) gx.URL { return gx.URL(\"/\") },\n\t},\n\t\"Empty\": {\n\t\tColumns: []Column[fixtureRow]{\n\t\t\t{Key: \"name\", Label: \"Name\", Cell: func(r fixtureRow) gx.Node { return gx.Text(r.Name) }},\n\t\t},\n\t\tPage: Page{Number: 1, Size: 10, Total: 0},\n\t\tHref: func(sort, dir string, page int) gx.URL { return gx.URL(\"/\") },\n\t},\n}\n```\n\n")}))}), gxContentMarkdown("\n\nThe theme must define these tokens: `--border`, `--muted-foreground`, `--accent`, `--accent-foreground`, `--ring`.\n\n## Usage\n\n```go\ntype Row struct {\n  Name  string\n  Total int\n}\n\nvar columns = []datatable.Column[Row]{\n  {Key: \"name\", Label: \"Name\", Sort: \"name\", Cell: func(r Row) gx.Node { return gx.Text(r.Name) }},\n  {Key: \"total\", Label: \"Total\", Cell: func(r Row) gx.Node { return gx.Text(strconv.Itoa(r.Total)) }},\n}\n\n// In the view:\ndatatable.DataTable(datatable.DataTableProps[Row]{\n  Columns: columns,\n  Rows:    p.Rows,\n  Page:    datatable.Page{Number: p.Page, Size: 25, Total: 10000},\n  Sort:    p.Sort,\n  Dir:     p.Dir,\n  Href: func(sort, dir string, page int) gx.URL {\n    return invoices.List{Sort: sort, Dir: dir, Page: page}.URL()\n  },\n})\n```\n\n## Examples\n\n### Three\n\n"), Example(ExampleProps{Item: "data-table", Name: "data-table-three", Label: "Data Table: Three", Children: gxContentMarkdown("\n\n```gx\n{datatable.DataTable(datatable.DataTableFixtures[\"Three\"])}\n```\n\nThe code renders the fixture by its name. The fixture sets these props.\n\n```go title=\"registry/data-table/DataTable.fixtures.go\"\n\"Three\": {\n  Columns: []Column[fixtureRow]{\n    {Key: \"name\", Label: \"Name\", Sort: \"name\", Cell: func(r fixtureRow) gx.Node { return gx.Text(r.Name) }},\n    {Key: \"total\", Label: \"Total\", Cell: func(r fixtureRow) gx.Node { return gx.Text(strconv.Itoa(r.Total)) }},\n  },\n  Rows: []fixtureRow{{Name: \"Alpha\", Total: 10}, {Name: \"Beta\", Total: 20}, {Name: \"Gamma\", Total: 30}},\n  Page: Page{Number: 1, Size: 10, Total: 3},\n  Href: func(sort, dir string, page int) gx.URL { return gx.URL(\"/\") },\n}\n```\n\n")}), gxContentMarkdown("\n\n### Empty\n\n"), Example(ExampleProps{Item: "data-table", Name: "data-table-empty", Label: "Data Table: Empty", Children: gxContentMarkdown("\n\n```gx\n{datatable.DataTable(datatable.DataTableFixtures[\"Empty\"])}\n```\n\nThe code renders the fixture by its name. The fixture sets these props.\n\n```go title=\"registry/data-table/DataTable.fixtures.go\"\n\"Empty\": {\n  Columns: []Column[fixtureRow]{\n    {Key: \"name\", Label: \"Name\", Cell: func(r fixtureRow) gx.Node { return gx.Text(r.Name) }},\n  },\n  Page: Page{Number: 1, Size: 10, Total: 0},\n  Href: func(sort, dir string, page int) gx.URL { return gx.URL(\"/\") },\n}\n```\n\n")}), gxContentMarkdown("\n\n## Do and don't\n\n"), docs.CardGrid(docs.CardGridProps{Children: gx.Frag(docs.Card(docs.CardProps{Title: "Do", Children: gxContentMarkdown("\n\n- Sort, filter and page on the server through a typed GET route.\n- Pass the current `Sort` and `Dir` back into the props.\n\n")}), docs.Card(docs.CardProps{Title: "Don't", Children: gxContentMarkdown("\n\n- Do not page on the client.\n- Do not render more rows than the page size.\n\n")}))}), gxContentMarkdown("\n\n## Keyboard\n\n| Key | Action |\n| --- | --- |\n| Tab | Moves between the sort headers and the page links. |\n| Enter | Sorts by the focused header or follows a page link. |\n"))
