		return gx.Frag(Example(ExampleProps{Item: "toast", Name: "toast-default", Label: "Toast: Toast: Default", Children: gxContentMarkdown("\n\n```gx\n{toast.Toast(toast.ToastFixtures[\"Default\"])}\n```\n\nThe code renders the fixture by its name. The fixture sets these props.\n\n```go title=\"registry/toast/Toast.fixtures.go\"\n\"Default\": {Class: fixtureWidth, Toast: gx.ToastPatch{Text: \"Event created\"}}\n```\n\n")}), docs.Aside(docs.AsideProps{Kind: docs.Note, Title: "Static preview", Children: gxContentMarkdown("\n\nThis page shows static fixtures. The live behaviour needs a server.\n\n")}), gxContentMarkdown("\n\n## Installation\n\n"), docs.Tabs(docs.TabsProps{Sync: "install", Children: gx.Frag(docs.TabItem(docs.TabItemProps{Label: "CLI", Children: gxContentMarkdown("\n\nRun the command in the app module.\n\n```sh frame=\"terminal\" title=\"Terminal\"\ngx add toast\n```\n\nThe command writes these files.\n\n| File | Path in the app |\n| --- | --- |\n| `Toaster.gx` | `ui/toast/Toaster.gx` |\n| `Toast.gx` | `ui/toast/Toast.gx` |\n| `icons.go` | `ui/toast/icons.go` |\n| `Toaster.fixtures.go` | `ui/toast/Toaster.fixtures.go` |\n| `Toast.fixtures.go` | `ui/toast/Toast.fixtures.go` |\n\n")}), docs.TabItem(docs.TabItemProps{Label: "Manual", Children: gxContentMarkdown("\n\nCopy each file to its path in the app. Change each import of a registry package to the path of that package in the app.\n\n```gx title=\"ui/toast/Toaster.gx\"\npackage toast\n\nprops {\n  Class    string   = \"\"\n  Children gx.Node  = nil\n  Attrs    gx.Attrs = nil\n}\n\n<div id=\"gx-toaster\" role=\"region\" aria-label=\"Notifications\" aria-live=\"polite\" data-gx-toaster class={gx.Cx(\"fixed right-4 bottom-4 z-50 flex w-[356px] max-w-[calc(100vw-2rem)] flex-col gap-3\", p.Class)} {...p.Attrs}>{p.Children}</div>\n```\n\n```gx title=\"ui/toast/Toast.gx\"\npackage toast\n\nprops {\n  Toast gx.ToastPatch\n  Class string   = \"\"\n  Attrs gx.Attrs = nil\n}\n\n<div class={gx.Cx(\"flex w-full items-start gap-2 rounded-lg border border-border bg-popover p-4 text-sm text-popover-foreground shadow-lg transition-[opacity,translate] duration-200 ease-out starting:translate-y-2 starting:opacity-0 data-[closing]:pointer-events-none data-[closing]:translate-x-4 data-[closing]:opacity-0 motion-reduce:transition-none\", p.Class)} {...gx.ToastAttrs(p.Toast)} {...p.Attrs}>\n  if p.icon() != \"\" {\n    {gx.Icon(p.icon(), gx.IconProps{Class: p.iconClass()})}\n  }\n  <div class=\"grid min-w-0 flex-1 gap-0.5\">\n    <div class=\"leading-5 font-medium\">{p.Toast.Text}</div>\n    if p.Toast.Description != \"\" {\n      <div class=\"leading-5 text-muted-foreground\">{p.Toast.Description}</div>\n    }\n  </div>\n  if p.Toast.Action.Label != \"\" {\n    <a href={p.Toast.Action.URL} class=\"inline-flex h-6 shrink-0 items-center rounded-md bg-primary px-2 text-xs font-medium text-primary-foreground outline-none hover:bg-primary/90 focus-visible:ring-[3px] focus-visible:ring-ring/50\">{p.Toast.Action.Label}</a>\n  }\n  <button type=\"button\" data-gx-close aria-label=\"Close\" class=\"-my-0.5 -mr-1 inline-flex size-6 shrink-0 items-center justify-center rounded-md text-muted-foreground outline-none hover:bg-accent hover:text-accent-foreground focus-visible:ring-[3px] focus-visible:ring-ring/50\">\n    {gx.Icon(iconX, gx.IconProps{Class: \"size-4\"})}\n  </button>\n</div>\n```\n\n```go title=\"ui/toast/icons.go\"\npackage toast\n\nimport \"github.com/alternayte/gx\"\n\n// The icon bodies come from Lucide (https://lucide.dev), ISC License,\n// Copyright (c) Lucide Contributors.\nconst (\n\ticonCircleCheck   = `<circle cx=\"12\" cy=\"12\" r=\"10\"/><path d=\"m9 12 2 2 4-4\"/>`\n\ticonInfo          = `<circle cx=\"12\" cy=\"12\" r=\"10\"/><path d=\"M12 16v-4\"/><path d=\"M12 8h.01\"/>`\n\ticonTriangleAlert = `<path d=\"m21.73 18-8-14a2 2 0 0 0-3.48 0l-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.73-3\"/><path d=\"M12 9v4\"/><path d=\"M12 17h.01\"/>`\n\ticonOctagonX      = `<path d=\"m15 9-6 6\"/><path d=\"M2.586 16.726A2 2 0 0 1 2 15.312V8.688a2 2 0 0 1 .586-1.414l4.688-4.688A2 2 0 0 1 8.688 2h6.624a2 2 0 0 1 1.414.586l4.688 4.688A2 2 0 0 1 22 8.688v6.624a2 2 0 0 1-.586 1.414l-4.688 4.688a2 2 0 0 1-1.414.586H8.688a2 2 0 0 1-1.414-.586z\"/><path d=\"m9 9 6 6\"/>`\n\ticonLoaderCircle  = `<path d=\"M21 12a9 9 0 1 1-6.219-8.56\"/>`\n\ticonX             = `<path d=\"M18 6 6 18\"/><path d=\"m6 6 12 12\"/>`\n)\n\n// icon returns the icon body of the toast kind, or \"\" for the default kind.\nfunc (p ToastProps) icon() string {\n\tswitch p.Toast.Kind {\n\tcase gx.ToastSuccess:\n\t\treturn iconCircleCheck\n\tcase gx.ToastInfo:\n\t\treturn iconInfo\n\tcase gx.ToastWarning:\n\t\treturn iconTriangleAlert\n\tcase gx.ToastError:\n\t\treturn iconOctagonX\n\tcase gx.ToastLoading:\n\t\treturn iconLoaderCircle\n\t}\n\treturn \"\"\n}\n\n// iconClass returns the classes of the kind icon. The icon sits on the first\n// text line, and the loading icon turns.\nfunc (p ToastProps) iconClass() string {\n\tconst base = \"mt-0.5 size-4 shrink-0\"\n\tif p.Toast.Kind == gx.ToastLoading {\n\t\treturn base + \" animate-spin motion-reduce:animate-none\"\n\t}\n\treturn base\n}\n\n// Render renders one pushed toast. An app passes it as gx.Config.Toast.\nfunc Render(p gx.ToastPatch) gx.Node {\n\treturn Toast(ToastProps{Toast: p})\n}\n```\n\n```go title=\"ui/toast/Toaster.fixtures.go\"\npackage toast\n\nimport \"github.com/alternayte/gx\"\n\n// The fixture toaster is static, so it stays inside its gallery section, and\n// its toast is sticky, so it stays for the audits.\nvar ToasterFixtures = gx.Fixtures[ToasterProps]{\n\t\"WithToast\": {Class: \"static\", Children: Render(gx.ToastPatch{Text: \"Saved\", Sticky: true})},\n}\n```\n\n```go title=\"ui/toast/Toast.fixtures.go\"\npackage toast\n\nimport \"github.com/alternayte/gx\"\n\n// fixtureWidth is the width a toast has inside the toaster.\nconst fixtureWidth = \"max-w-[356px]\"\n\nvar ToastFixtures = gx.Fixtures[ToastProps]{\n\t\"Default\": {Class: fixtureWidth, Toast: gx.ToastPatch{Text: \"Event created\"}},\n\t\"Success\": {Class: fixtureWidth, Toast: gx.ToastPatch{Kind: gx.ToastSuccess, Text: \"Changes saved\"}},\n\t\"Info\":    {Class: fixtureWidth, Toast: gx.ToastPatch{Kind: gx.ToastInfo, Text: \"A new version is available\"}},\n\t\"Warning\": {Class: fixtureWidth, Toast: gx.ToastPatch{Kind: gx.ToastWarning, Text: \"Your trial ends in 3 days\"}},\n\t\"Error\":   {Class: fixtureWidth, Toast: gx.ToastPatch{Kind: gx.ToastError, Text: \"The upload failed\"}},\n\t\"Loading\": {Class: fixtureWidth, Toast: gx.ToastPatch{Kind: gx.ToastLoading, Text: \"Uploading the file\"}},\n\t\"WithDescription\": {Class: fixtureWidth, Toast: gx.ToastPatch{\n\t\tKind:        gx.ToastSuccess,\n\t\tText:        \"Event created\",\n\t\tDescription: \"Monday, 12 January at 09:00\",\n\t}},\n\t\"WithAction\": {Class: fixtureWidth, Toast: gx.ToastPatch{\n\t\tText:        \"Item added to the cart\",\n\t\tDescription: \"Open the cart to check out.\",\n\t\tAction:      gx.ToastAction{Label: \"View\", URL: \"/\"},\n\t}},\n}\n```\n\n")}))}), gxContentMarkdown("\n\nThe theme must define these tokens: `--popover`, `--popover-foreground`, `--border`, `--muted-foreground`, `--primary`, `--primary-foreground`, `--accent`, `--accent-foreground`, `--ring`.\n\n## Usage\n\nRender the toaster once, in the root layout.\n\n```gx\n<toast.Toaster />\n```\n\nPass `toast.Render` to the app. The app then renders every pushed toast with the `Toast` component of this item.\n\n```go\napp := gx.New(gx.Config{Adapter: datastar.Adapter(), Toast: toast.Render})\n```\n\nAn action or a form pushes a toast.\n\n```go\nreturn c.Toast(\"Saved\")\n```\n\nA kind is an option. The kinds are `gx.ToastDefault`, `gx.ToastSuccess`, `gx.ToastInfo`, `gx.ToastWarning`, `gx.ToastError` and `gx.ToastLoading`.\n\n```go\nreturn c.Toast(\"Changes saved\", gx.ToastSuccess)\n```\n\nAdd a description, a duration or a link to a route.\n\n```go\nreturn c.Toast(\"Item added to the cart\",\n\tgx.ToastDescription(\"Open the cart to check out.\"),\n\tgx.ToastDuration(8*time.Second),\n\tgx.ToastLink(\"View\", route.Cart{}))\n```\n\nA toast leaves after 4 seconds. A loading toast and a `gx.ToastSticky` toast stay until the user closes them.\n\nGive two toasts the same ID. The second toast replaces the first in place.\n\n```go\n// The first action.\nreturn c.Toast(\"Uploading the file\", gx.ToastLoading, gx.ToastID(\"upload\"))\n\n// A later action.\nreturn c.Toast(\"File uploaded\", gx.ToastSuccess, gx.ToastID(\"upload\"))\n```\n\nA failed action or form pushes its error as a `gx.ToastError` toast.\n\nThe toaster shows at most three toasts. The oldest toast leaves first.\n\n## Examples\n\n### Toast: Default\n\n"), Example(ExampleProps{Item: "toast", Name: "toast-default", Label: "Toast: Toast: Default", Children: gxContentMarkdown("\n\n```gx\n{toast.Toast(toast.ToastFixtures[\"Default\"])}\n```\n\nThe code renders the fixture by its name. The fixture sets these props.\n\n```go title=\"registry/toast/Toast.fixtures.go\"\n\"Default\": {Class: fixtureWidth, Toast: gx.ToastPatch{Text: \"Event created\"}}\n```\n\n")}), gxContentMarkdown("\n\n### Toast: Success\n\n"), Example(ExampleProps{Item: "toast", Name: "toast-success", Label: "Toast: Toast: Success", Children: gxContentMarkdown("\n\n```gx\n{toast.Toast(toast.ToastFixtures[\"Success\"])}\n```\n\nThe code renders the fixture by its name. The fixture sets these props.\n\n```go title=\"registry/toast/Toast.fixtures.go\"\n\"Success\": {Class: fixtureWidth, Toast: gx.ToastPatch{Kind: gx.ToastSuccess, Text: \"Changes saved\"}}\n```\n\n")}), gxContentMarkdown("\n\n### Toast: Info\n\n"), Example(ExampleProps{Item: "toast", Name: "toast-info", Label: "Toast: Toast: Info", Children: gxContentMarkdown("\n\n```gx\n{toast.Toast(toast.ToastFixtures[\"Info\"])}\n```\n\nThe code renders the fixture by its name. The fixture sets these props.\n\n```go title=\"registry/toast/Toast.fixtures.go\"\n\"Info\":    {Class: fixtureWidth, Toast: gx.ToastPatch{Kind: gx.ToastInfo, Text: \"A new version is available\"}}\n```\n\n")}), gxContentMarkdown("\n\n### Toast: Warning\n\n"), Example(ExampleProps{Item: "toast", Name: "toast-warning", Label: "Toast: Toast: Warning", Children: gxContentMarkdown("\n\n```gx\n{toast.Toast(toast.ToastFixtures[\"Warning\"])}\n```\n\nThe code renders the fixture by its name. The fixture sets these props.\n\n```go title=\"registry/toast/Toast.fixtures.go\"\n\"Warning\": {Class: fixtureWidth, Toast: gx.ToastPatch{Kind: gx.ToastWarning, Text: \"Your trial ends in 3 days\"}}\n```\n\n")}), gxContentMarkdown("\n\n### Toast: Error\n\n"), Example(ExampleProps{Item: "toast", Name: "toast-error", Label: "Toast: Toast: Error", Children: gxContentMarkdown("\n\n```gx\n{toast.Toast(toast.ToastFixtures[\"Error\"])}\n```\n\nThe code renders the fixture by its name. The fixture sets these props.\n\n```go title=\"registry/toast/Toast.fixtures.go\"\n\"Error\":   {Class: fixtureWidth, Toast: gx.ToastPatch{Kind: gx.ToastError, Text: \"The upload failed\"}}\n```\n\n")}), gxContentMarkdown("\n\n### Toast: Loading\n\n"), Example(ExampleProps{Item: "toast", Name: "toast-loading", Label: "Toast: Toast: Loading", Children: gxContentMarkdown("\n\n```gx\n{toast.Toast(toast.ToastFixtures[\"Loading\"])}\n```\n\nThe code renders the fixture by its name. The fixture sets these props.\n\n```go title=\"registry/toast/Toast.fixtures.go\"\n\"Loading\": {Class: fixtureWidth, Toast: gx.ToastPatch{Kind: gx.ToastLoading, Text: \"Uploading the file\"}}\n```\n\n")}), gxContentMarkdown("\n\n### Toast: With description\n\n"), Example(ExampleProps{Item: "toast", Name: "toast-with-description", Label: "Toast: Toast: With description", Children: gxContentMarkdown("\n\n```gx\n{toast.Toast(toast.ToastFixtures[\"WithDescription\"])}\n```\n\nThe code renders the fixture by its name. The fixture sets these props.\n\n```go title=\"registry/toast/Toast.fixtures.go\"\n\"WithDescription\": {Class: fixtureWidth, Toast: gx.ToastPatch{\n  Kind:        gx.ToastSuccess,\n  Text:        \"Event created\",\n  Description: \"Monday, 12 January at 09:00\",\n}}\n```\n\n")}), gxContentMarkdown("\n\n### Toast: With action\n\n"), Example(ExampleProps{Item: "toast", Name: "toast-with-action", Label: "Toast: Toast: With action", Children: gxContentMarkdown("\n\n```gx\n{toast.Toast(toast.ToastFixtures[\"WithAction\"])}\n```\n\nThe code renders the fixture by its name. The fixture sets these props.\n\n```go title=\"registry/toast/Toast.fixtures.go\"\n\"WithAction\": {Class: fixtureWidth, Toast: gx.ToastPatch{\n  Text:        \"Item added to the cart\",\n  Description: \"Open the cart to check out.\",\n  Action:      gx.ToastAction{Label: \"View\", URL: \"/\"},\n}}\n```\n\n")}), gxContentMarkdown("\n\n### Toaster: With toast\n\n"), Example(ExampleProps{Item: "toast", Name: "toaster-with-toast", Label: "Toast: Toaster: With toast", Children: gxContentMarkdown("\n\n```gx\n<toast.Toaster class=\"static\">{toast.Render(gx.ToastPatch{Text: \"Saved\", Sticky: true})}</toast.Toaster>\n```\n\n")}), gxContentMarkdown("\n\n## Do and don't\n\n"), docs.CardGrid(docs.CardGridProps{Children: gx.Frag(docs.Card(docs.CardProps{Title: "Do", Children: gxContentMarkdown("\n\n- Render one toaster in the root layout.\n- Set `Toast: toast.Render` in `gx.Config`.\n- Keep the text short. Put detail in the description.\n- Use one ID for the steps of one operation.\n\n")}), docs.Card(docs.CardProps{Title: "Don't", Children: gxContentMarkdown("\n\n- Do not render a toaster per page.\n- Do not use a toast for a value the user must not miss. Use an alert.\n- Do not put the only path to a task in a toast link. The toast leaves.\n- Do not write toast classes in package `gx` code. Change `Toast.gx`.\n\n")}))}), gxContentMarkdown("\n\n## Keyboard\n\n| Key | Action |\n| --- | --- |\n| Tab | Moves focus to the link and the close button of a toast. The timers stop while focus is in the toaster. |\n| Enter | Follows the focused link, or closes the toast on the close button. |\n| Space | Closes the toast on the close button. |\n| Escape | Closes the toast that holds focus. Focus returns to the element that had it before the toaster. |\n"))
